import{_ as o,C as n,o as s,c as r,ah as e,E as i}from"./chunks/framework.sPHStHqt.js";const f=JSON.parse('{"title":"Custom Domains","description":"","frontmatter":{},"headers":[],"relativePath":"tenants/custom-domains.md","filePath":"tenants/custom-domains.md","lastUpdated":1789630599000}'),h={name:"tenants/custom-domains.md"};function m(d,t,l,c,u,p){const a=n("ImagePopup");return s(),r("div",null,[t[0]||(t[0]=e('<h1 id="custom-domains" tabindex="-1">Custom Domains <a class="header-anchor" href="#custom-domains" aria-label="Permalink to &quot;Custom Domains&quot;">​</a></h1><p><em>This page serves <strong>both</strong> audiences — a <strong>tenant</strong> who wants their CRM on their own domain, and the <strong>operator</strong> setting one up on a tenant&#39;s behalf.</em></p><p>By default a tenant&#39;s CRM lives on a subdomain of the platform — <code>acme.yourplatform.com</code>. A <strong>custom domain</strong> (a &quot;CName&quot;) lets that same CRM answer on the tenant&#39;s own address instead, like <code>crm.acmeconsulting.com</code>.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What a custom domain is and when to use one</li><li>The two things it takes to set one up</li><li>Where to enter it, as a tenant or as the operator</li></ul></div><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>A custom domain doesn&#39;t move or copy anything — it&#39;s a second front door to the same CRM. The tenant&#39;s data, users and settings are unchanged; only the address people type changes.</p><p>Setting one up has two halves, and <strong>both</strong> are required:</p><ol><li><strong>Point the domain at the platform.</strong> In the domain&#39;s DNS, add a <strong>CNAME record</strong> for the hostname (e.g. <code>crm</code>) that points at the platform. This is done with the tenant&#39;s domain registrar or DNS provider — not inside Krayin.</li><li><strong>Tell Krayin the domain.</strong> Enter the same hostname in the tenant&#39;s <strong>CName</strong> field so the platform knows to serve that tenant when the domain is requested.</li></ol><p>If either half is missing, the custom domain won&#39;t load.</p><h2 id="entering-the-domain" tabindex="-1">Entering the domain <a class="header-anchor" href="#entering-the-domain" aria-label="Permalink to &quot;Entering the domain&quot;">​</a></h2><p>Wherever it appears, the <strong>CName</strong> field is the same. It takes a bare hostname — <code>crm.acmeconsulting.com</code> — with no <code>http://</code> and no trailing path.</p>',11)),i(a,{src:"/images/custom-domains/cname-field.png",alt:"The CName field on the tenant form"}),t[1]||(t[1]=e('<p>The field&#39;s hint says it plainly: <em>&quot;Optional. Point a CNAME record for this domain at the platform, then enter it here, e.g. crm.example.com.&quot;</em> Two rules are enforced when you save:</p><ul><li><strong>It must be a valid bare domain.</strong> A bad value is rejected with <em>&quot;Enter a valid domain such as crm.example.com, without http:// or a trailing path.&quot;</em></li><li><strong>Each domain belongs to only one tenant.</strong> Reusing one already taken is rejected with <em>&quot;This domain is already assigned to another tenant.&quot;</em></li></ul><h3 id="as-a-tenant" tabindex="-1">As a tenant <a class="header-anchor" href="#as-a-tenant" aria-label="Permalink to &quot;As a tenant&quot;">​</a></h3><p>You can set your CName during <a href="/tenants/registration">registration</a>, in <strong>Step 1 — Organization Details</strong>. Leave it blank if you&#39;re happy on your platform subdomain — you can always ask your platform operator to add or change it later.</p><h3 id="as-the-operator" tabindex="-1">As the operator <a class="header-anchor" href="#as-the-operator" aria-label="Permalink to &quot;As the operator&quot;">​</a></h3><p>On the tenant&#39;s <strong>create</strong> or <strong>edit</strong> form, fill in the <strong>CName</strong> field (shown above). It&#39;s the same field either way, so you can add a custom domain to an existing tenant at any time by editing them — see <a href="/super-admin/tenant-management">Tenant Management</a> for the full form.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A tenant can always still reach their CRM on the original <code>username.yourplatform.com</code> subdomain, even after a custom domain is added. The custom domain is an addition, not a replacement.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A custom domain only works once its DNS CNAME record has propagated. DNS changes can take anywhere from a few minutes to a few hours to take effect — if the domain doesn&#39;t load right away, that&#39;s the usual reason.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>The tenant form where the operator sets this → <a href="/super-admin/tenant-management">Tenant Management</a></li><li>How addresses and tenancy work under the hood → <a href="/getting-started/architecture">Architecture</a></li><li>Set your CName while signing up → <a href="/tenants/registration">Registration</a></li></ul>',10))])}const w=o(h,[["render",m]]);export{f as __pageData,w as default};
